contract InvMutTest {
    C c;

    event Dummy();

    constructor(C _c) {
        c = _c;
    }

    // We take inputs controlling encodedParameters and ownedBy, and also allow toggling who is a program operator
    // The test will try to call create and then assert a general invariant: if create succeeds (not reverted),
    // then the returned address is a contract (code.length > 0) and matches that a snapshot of c.roundImplementation()
    // at the time of call is equal to the RoundImplementation emitted in the RoundCreated event. We cannot read
    // emitted events here, so instead we assert that c.roundImplementation() is non-zero and that the created clone
    // has non-zero code. This enforces that create produces a deployed clone when it does not revert.

    // Note: msg.sender for calls on c is this contract. The caller must be a program operator. We therefore accept
    // a boolean to decide whether to set ourselves as a program operator by interacting with c.programOperators mapping
    // — but mapping has public getter and programOperators is public so we can only read it; we cannot write it because
    // there's no setter. Instead, we rely on the fact that the freshly deployed factory has an owner (the deployer) and
    // our contract deployed it in the harness; however constraints prevent assuming that. To make the test general and
    // safe, we call create and record whether it reverted. If it succeeds, we assert the clone has code and that
    // factory.roundImplementation() was non-zero. If it reverts, we make no stronger claim.

    function run(bytes calldata encodedParameters, address ownedBy) public payable {
        require(true);

        bool reverted;
        address cloneAddr;
        // Call create and catch revert
        try c.create(encodedParameters, ownedBy) returns (address _clone) {
            reverted = false;
            cloneAddr = _clone;
        } catch {
            reverted = true;
            cloneAddr = address(0);
        }

        // Read factory's roundImplementation after the call
        address currentImpl = c.roundImplementation();

        // General rule (single assert): if create did not revert then the created address must be a contract
        // (have non-zero code) and the factory's roundImplementation at observation time must be non-zero
        // (since creation requires it non-zero). This ties the observable effect (deployed clone) to the factory's
        // required invariant.
        assert(reverted || (cloneAddr != address(0) && address(codeSizeContractHelper(cloneAddr)) != address(0) && currentImpl != address(0)));
    }

    // Helper: wrapper to get code size by returning an address whose balance equals code.size>0 ? 1 wei : 0 wei.
    // However, we cannot perform external assembly in the assert; instead we implement a small internal view that
    // uses extcodesize via assembly and returns a dummy address: address(1) if code>0 else address(0).
    function codeSizeContractHelper(address target) internal view returns (address) {
        uint256 size;
        assembly { size := extcodesize(target) }
        if (size > 0) return address(1);
        return address(0);
    }

    // receive to accept any refunds if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Single public entry performing the property check
    function run(bytes calldata encodedParameters, address ownedBy) public payable {
        require(true);

        // Capture pre-call observables that are public: roundImplementation and alloSettings
        address implBefore = c.roundImplementation();
        address settingsBefore = c.alloSettings();

        bool reverted;
        address cloneAddr;

        // Make the state-changing call as a top-level statement and catch revert
        try c.create(encodedParameters, ownedBy) returns (address _clone) {
            reverted = false;
            cloneAddr = _clone;
        } catch {
            reverted = true;
            cloneAddr = address(0);
        }

        // Read post-call observable: roundImplementation again (allowed)
        address implAfter = c.roundImplementation();

        // Check code size of cloneAddr via extcodesize (allowed read from address)
        uint256 codeSize;
        if (cloneAddr != address(0)) {
            assembly { codeSize := extcodesize(cloneAddr) }
        } else {
            codeSize = 0;
        }

        // General rule (single assert): if create succeeded then returned address is non-zero and has non-zero code
        // If create reverted then at least one of the factory preconditions was not met: implBefore==0 or settingsBefore==0
        // We also allow the case where create reverted for other reasons, but require that if it reverted then
        // (implBefore==address(0) || settingsBefore==address(0)). This ties observable failure to the documented requires.
        assert((!reverted && cloneAddr != address(0) && codeSize > 0) || (reverted && (implBefore == address(0) || settingsBefore == address(0))));
    }

    receive() external payable {}
}

