    receive() external payable {}

    // params: encodedParameters passed-through, ownedBy as provided, and a flag to set this contract as a program operator
    function run(bytes calldata encodedParameters, address ownedBy, bool makeProgramOperator) public payable {
        // Precondition: this test must be the deployer/owner of c per harness description; but we cannot require on c state.
        // Ensure this contract has some balance if the create path attempted to send/require value (not used by P but safe)
        if (msg.value > 0) {
            require(address(this).balance >= msg.value, "balance");
        }

        // Make this contract a program operator if requested by calling c.programOperators mapping via delegate call not possible;
        // But we can call c.updateAlloSettings and c.updateRoundImplementation only if owner; however the checker deploys c freshly and the InvMutTest contract is the deployer.
        // Try to initialize required state: set alloSettings and roundImplementation and programOperator mapping.

        // Set alloSettings to some non-zero address (use ownedBy or this)
        address someSettings = ownedBy == address(0) ? address(this) : ownedBy;
        // set roundImplementation to this contract address (non-zero) via updateRoundImplementation; onlyOwner can call — the test contract is the deployer per harness assumption
        // These state-changing calls must be top-level statements.
        c.updateAlloSettings(someSettings);
        c.updateRoundImplementation(payable(address(this)));

        // Grant this contract program operator rights by directly writing to mapping is impossible externally; instead rely on the possibility that c's deployer (this) is owner and can set programOperators mapping externally isn't available.
        // But mapping programOperators is public; cannot set from outside. To make caller be a program operator we instead attempt create and capture revert flag — property will relate revert to returned address.

        bool reverted;
        address ret;
        try c.create(encodedParameters, ownedBy) returns (address addr) {
            reverted = false;
            ret = addr;
        } catch {
            reverted = true;
            ret = address(0);
        }

        // General rule: create must not succeed returning address(0). If it reverted, that's acceptable. So: either reverted==true OR ret != address(0).
        assert(reverted || ret != address(0));
    }
}

