contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will exercise C.create. Parameters:
    // - encodedParameters: arbitrary bytes passed to initialize
    // - ownedBy: owner address for the created round
    function run(bytes calldata encodedParameters, address ownedBy, address newRoundImpl, address newAlloSettings, address programOperator) public payable {
        // Precondition: this test contract is the owner of c (the harness deployer will ensure this in the checker)
        // We require addresses are non-zero where needed so that update functions accept them
        require(newRoundImpl != address(0) && newAlloSettings != address(0), "impl/allo zero");

        // 1) Set roundImplementation and alloSettings via owner-only functions. The InvMutTest contract is the deployer/owner per harness.
        c.updateRoundImplementation(payable(newRoundImpl));
        c.updateAlloSettings(newAlloSettings);

        // 2) Make programOperator an authorized operator by writing directly to c.programOperators map is not allowed
        // so we must rely on the public surface: there is no setter in C other than owner-only ones for programOperators.
        // But programOperators is public storage (mapping) with auto-getter; we cannot set it except if owner did —
        // To allow exercising both behaviors, we branch by attempting the create call as either an authorized caller
        // or an unauthorized caller. Since calls to c that mutate must be top-level, perform both attempts using try/catch.

        // Prepare call data for create
        bool reverted;
        address retAddress = address(0);

        // First attempt: call create as this contract (msg.sender = InvMutTest). It will succeed only if programOperators[this] is true.
        try c.create(encodedParameters, ownedBy) returns (address addr) {
            reverted = false;
            retAddress = addr;
        } catch {
            reverted = true;
        }

        // If it did not revert, then the contract must have returned a non-zero address and that address must not be the zero address.
        // If it reverted, then at least one of the required conditions failed: either programOperators[msg.sender] was false,
        // or roundImplementation/alloSettings checks failed (we set them non-zero), so the expected general invariant is:
        // "create either reverts, or returns a non-zero address". This rules out successful creation returning zero.

        assert(reverted || (retAddress != address(0)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We require: caller (this) is the owner of c when calling owner-only functions.
    // Parameters:
    // - encodedParameters: passed to the round initialize
    // - ownedBy: passed to create
    // - newRoundImpl: non-zero address to set as roundImplementation
    // - newAlloSettings: non-zero address to set as alloSettings
    // - programOperator: address that we will mark as a program operator by relying on create behavior (we cannot write programOperators mapping),
    //   so we will attempt create from two different senders: this contract and via a delegate call simulation is not possible —
    //   instead we check the following general rule for the case where create succeeds: the returned clone's code-origin correlates with factory.roundImplementation.
    function run(bytes calldata encodedParameters, address ownedBy, address newRoundImpl, address newAlloSettings) public payable {
        require(newRoundImpl != address(0) && newAlloSettings != address(0), "impl/allo zero");

        // 1) Set the required implementation and settings as owner (test harness ensures this contract is owner of c)
        c.updateRoundImplementation(payable(newRoundImpl));
        c.updateAlloSettings(newAlloSettings);

        // 2) Try to call create. It may revert if this contract is not a program operator. Capture whether it reverted and the returned address.
        bool reverted;
        address cloneAddress;
        try c.create(encodedParameters, ownedBy) returns (address a) {
            reverted = false;
            cloneAddress = a;
        } catch {
            reverted = true;
            cloneAddress = address(0);
        }

        // General rule: if create succeeded (did not revert), then the returned address must be non-zero
        // and the code at that address must be non-empty (i.e., it's a contract). Additionally, when create succeeds
        // the factory's roundImplementation getter must equal the newRoundImpl we set earlier.
        // We can observe: c.roundImplementation() and code.length at cloneAddress via extcodesize observable as cloneAddress.code.length.
        // Formulate single assert combining these observations. Note: reading cloneAddress.code.length is allowed (public surface: address(code)).
        assert(reverted || (cloneAddress != address(0) && cloneAddress.code.length > 0 && c.roundImplementation() == newRoundImpl));
    }

    receive() external payable {}
}

contract InvMutTest {
