        // Set required factory config as owner
        c.updateRoundImplementation(payable(newRoundImpl));
        c.updateAlloSettings(newAlloSettings);

        // Read alloSettings before attempting create
        address alloBefore = c.alloSettings();

        // Attempt create; it may revert (e.g., if this contract is not a program operator).
        bool reverted;
        address cloneAddr;
        try c.create(encodedParameters, ownedBy) returns (address a) {
            reverted = false;
            cloneAddr = a;
