    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // - newRoundImpl: address to set as roundImplementation (must be non-zero)
    // - newAlloSettings: address to set as alloSettings (may be zero or non-zero)
    function run(address newRoundImpl, address newAlloSettings) public payable {
        require(newRoundImpl != address(0));

        // Ensure caller is owner by relying on the test deployment semantics: the checker deploys a fresh C
        // and then deploys this test with that C passed in; however, to be safe we first initialize C (owner setup)
        // The contract C is already deployed and initialized by the harness, so we must act as owner to call owner-only functions.
        // According to the problem statement, msg.sender for calls on c will be this contract (the test), and the checker
        // deploys a fresh c and then runs run once. To be able to call owner-only functions we therefore first attempt
        // to call updateAlloSettings and updateRoundImplementation; if we are not owner those calls will revert and we
        // capture that and still assert the general property relative to whether the call reverted.

        // Read alloSettings before any state-changing call
        address alloBefore = c.alloSettings();

        // Try to update roundImplementation; it may revert if this contract is not owner.
        bool updReverted;
        try c.updateRoundImplementation(payable(newRoundImpl)) {
            updReverted = false;
        } catch {
            updReverted = true;
        }

        // After attempt, read roundImplementation and alloSettings
        address roundImplAfter = c.roundImplementation();
        address alloAfter = c.alloSettings();

        // General rule (assert): If the updateRoundImplementation call succeeded then
        // - roundImplementation equals the requested newRoundImpl,
        // - and alloSettings was not changed by that call (alloAfter == alloBefore).
        // If the update reverted, then we make no claim about roundImplementation/alloSettings.
        assert(updReverted || (roundImplAfter == newRoundImpl && alloAfter == alloBefore));
    }

    receive() external payable {}
}

